//! The private, generic core of the verifiable OPRF modes.
//!
//! Everything that branches lives here, written once over [`VoprfGroup`] and
//! instantiated per ciphersuite. The public types in `api.rs` are generated by
//! a macro and only delegate. The split is deliberate: cargo-mutants does not
//! mutate the bodies of `macro_rules!` expansions, so any logic placed in the
//! generated wrappers would be invisible to it.
//!
//! Names follow RFC 9497: `skS` / `pkS` are the server key pair, `t` is the
//! POPRF tweaked private key, `C` / `D` are the DLEQ proof's element lists and
//! `M` / `Z` their composites (§2.2).

use alloc::vec::Vec;

use digest::Digest;
use pakery_core::ct;
use rand_core::CryptoRng;
use subtle::{Choice, ConstantTimeEq};
use zeroize::{Zeroize, Zeroizing};

use super::VoprfError;

/// RFC 9497 inputs are length-prefixed with two bytes (§1.2), so none can be
/// longer than this. §1.2 says inputs are "no larger than 2^16 - 1 bytes" and
/// §5.1 that they "MUST be smaller than 2^16 - 1 bytes"; the bound taken here
/// is the larger one, the most the two-byte prefix can encode.
pub(crate) const MAX_INPUT_LEN: usize = u16::MAX as usize;

/// The largest batch accepted. The composite transcript encodes each element's
/// index with `I2OSP(i, 2)` (§2.2.1), which would allow 65536 elements; one
/// fewer keeps the count itself representable in two bytes, as other
/// implementations do.
pub(crate) const MAX_BATCH_LEN: usize = u16::MAX as usize;

/// The domain separation tags of one (ciphersuite, mode) pair.
///
/// Every tag embeds `contextString = "OPRFV1-" || I2OSP(mode, 1) || "-" ||
/// identifier` (§3.1). Each suite writes its tags out as byte literals so they
/// can be read against RFC 9497 directly; a unit test rebuilds every one of
/// them from `CreateContextString` to catch a typo in either place.
#[derive(Clone, Copy)]
pub(crate) struct ModeDsts {
    /// `"HashToGroup-" || contextString` (§4).
    pub(crate) hash_to_group: &'static [u8],
    /// `"HashToScalar-" || contextString` (§4).
    pub(crate) hash_to_scalar: &'static [u8],
    /// `"DeriveKeyPair" || contextString` (§3.2.1) — no hyphen.
    pub(crate) derive_key_pair: &'static [u8],
    /// `seedDST = "Seed-" || contextString` (§2.2.1). Hashed, length-prefixed,
    /// into the composite seed; not an `expand_message` DST.
    pub(crate) seed: &'static [u8],
    /// `"pakery-DLEQNonce-" || contextString`: the tag of the hedged proof
    /// nonce, which is this crate's construction rather than the RFC's (see
    /// [`hedged_nonce`]).
    pub(crate) nonce: &'static [u8],
}

/// The prime-order group, hash and encodings of one RFC 9497 ciphersuite.
///
/// Implemented only for the private suite markers of this module; nothing
/// outside the crate can name it.
pub(crate) trait VoprfGroup: Sized + 'static {
    /// A scalar of the group.
    type Scalar: Copy + ConstantTimeEq + Zeroize;
    /// An element of the group.
    type Point: Copy + ConstantTimeEq + Zeroize;
    /// The ciphersuite hash (`Hash` in RFC 9497, output `Nh` bytes).
    type Hash: Digest;
    /// A serialized element, `[u8; Ne]`.
    type Element: Copy + Eq + AsRef<[u8]> + Zeroize + for<'a> TryFrom<&'a [u8]>;
    /// A PRF output, `[u8; Nh]`.
    type Output: AsRef<[u8]> + AsMut<[u8]> + Zeroize;

    /// `Ne`.
    const ELEMENT_LEN: usize;
    /// An all-zero output buffer, written over by the finalize hash.
    const OUTPUT_ZERO: Self::Output;
    /// The VOPRF (`0x01`) tags.
    const VOPRF: ModeDsts;
    /// The POPRF (`0x02`) tags.
    const POPRF: ModeDsts;

    /// The identity element.
    fn identity() -> Self::Point;
    /// `k * G`, constant time.
    fn mul_base(k: &Self::Scalar) -> Self::Point;
    /// `k * p`, constant time.
    fn mul(p: &Self::Point, k: &Self::Scalar) -> Self::Point;
    /// `a + b`.
    fn add(a: &Self::Point, b: &Self::Point) -> Self::Point;
    /// The zero scalar.
    fn scalar_zero() -> Self::Scalar;
    /// `a + b mod p`.
    fn scalar_add(a: &Self::Scalar, b: &Self::Scalar) -> Self::Scalar;
    /// `a - b mod p`.
    fn scalar_sub(a: &Self::Scalar, b: &Self::Scalar) -> Self::Scalar;
    /// `a * b mod p`.
    fn scalar_mul(a: &Self::Scalar, b: &Self::Scalar) -> Self::Scalar;
    /// `a^-1 mod p`, constant time. The caller has rejected `a = 0`: the
    /// implementations differ on what zero would return.
    fn scalar_invert(a: &Self::Scalar) -> Self::Scalar;
    /// `RandomScalar()`: a uniformly random nonzero scalar (RFC 9497 §2.1, and
    /// §4 as corrected by erratum 8392). Each suite consumes RNG bytes in the
    /// pattern its tests and the reference implementation rely on.
    fn random_scalar(rng: &mut impl CryptoRng) -> Self::Scalar;
    /// Reduce 64 caller-supplied uniform bytes modulo the group order.
    #[cfg(any(test, feature = "hazmat"))]
    fn scalar_from_wide(bytes: &[u8; 64]) -> Self::Scalar;
    /// `HashToGroup(input)` with the given DST.
    fn hash_to_group(input: &[u8], dst: &[u8]) -> Result<Self::Point, VoprfError>;
    /// `HashToScalar(concat(msg))` with the given DST.
    fn hash_to_scalar(msg: &[&[u8]], dst: &[u8]) -> Self::Scalar;
    /// `SerializeElement`, constant time, for a point the caller knows is not
    /// the identity. P-256 cannot encode the identity in `Ne` bytes, and this
    /// encoder would return the encoding of a different, valid point for it
    /// (`0x02 || 0^32`: `x = 0` is on the curve), so a missed check would be
    /// silent. Call it only where the identity is excluded by construction —
    /// a nonzero scalar times the generator or a non-identity point — and go
    /// through [`encode_nonidentity`] everywhere else.
    fn encode_element_unchecked(p: &Self::Point) -> Self::Element;
    /// `DeserializeElement`: `None` unless `bytes` is the canonical encoding of
    /// a group element other than the identity.
    fn decode_element(bytes: &[u8]) -> Option<Self::Point>;
    /// `SerializeScalar`.
    fn encode_scalar(s: &Self::Scalar) -> [u8; 32];
    /// `DeserializeScalar`, constant time: the scalar (zero when invalid) and
    /// whether `bytes` was its canonical encoding.
    fn decode_scalar(bytes: &[u8; 32]) -> (Self::Scalar, Choice);
}

/// Which protocol variant an operation runs, with the POPRF's public input.
#[derive(Clone, Copy)]
pub(crate) enum Mode<'a> {
    /// RFC 9497 §3.3.2.
    Voprf,
    /// RFC 9497 §3.3.3, with its `info`.
    Poprf(&'a [u8]),
}

impl Mode<'_> {
    fn dsts<G: VoprfGroup>(self) -> ModeDsts {
        match self {
            Mode::Voprf => G::VOPRF,
            Mode::Poprf(_) => G::POPRF,
        }
    }
}

/// A group element together with its serialization.
pub(crate) struct Elem<G: VoprfGroup> {
    point: G::Point,
    bytes: G::Element,
}

impl<G: VoprfGroup> Clone for Elem<G> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<G: VoprfGroup> Copy for Elem<G> {}

/// One `(C[i], D[i])` pair of a DLEQ statement `k * C[i] == D[i]`.
struct DleqPair<G: VoprfGroup> {
    c: Elem<G>,
    d: Elem<G>,
}

/// `I2OSP(len, 2)` for a length this module bounds by construction — element,
/// scalar and digest sizes, and batch indices below [`MAX_BATCH_LEN`].
fn i2osp2(len: usize) -> [u8; 2] {
    debug_assert!(len <= MAX_INPUT_LEN);
    (len as u16).to_be_bytes()
}

/// `I2OSP(len(data), 2)` for caller data, which may be too long.
fn length_prefix(data: &[u8]) -> Result<[u8; 2], VoprfError> {
    u16::try_from(data.len())
        .map(u16::to_be_bytes)
        .map_err(|_| VoprfError::InputTooLong)
}

fn check_batch_len(len: usize) -> Result<(), VoprfError> {
    if len == 0 || len > MAX_BATCH_LEN {
        return Err(VoprfError::Batch);
    }
    Ok(())
}

/// Reject the identity, then serialize. The identity check is an abort
/// decision, so declassifying it is safe even for a secret point.
fn encode_nonidentity<G: VoprfGroup>(
    p: &G::Point,
    on_identity: VoprfError,
) -> Result<G::Element, VoprfError> {
    if ct::declassify_choice(p.ct_eq(&G::identity())) {
        return Err(on_identity);
    }
    Ok(G::encode_element_unchecked(p))
}

fn decode_elem<G: VoprfGroup>(bytes: &[u8]) -> Result<Elem<G>, VoprfError> {
    let point = G::decode_element(bytes).ok_or(VoprfError::Deserialize)?;
    let bytes = G::Element::try_from(bytes).map_err(|_| VoprfError::Deserialize)?;
    Ok(Elem { point, bytes })
}

/// `m = HashToScalar("Info" || I2OSP(len(info), 2) || info)` (§3.3.3).
fn info_scalar<G: VoprfGroup>(dsts: &ModeDsts, info: &[u8]) -> Result<G::Scalar, VoprfError> {
    let info_len = length_prefix(info)?;
    Ok(G::hash_to_scalar(
        &[b"Info", &info_len, info],
        dsts.hash_to_scalar,
    ))
}

// ---------------------------------------------------------------------------
// DLEQ proofs (RFC 9497 §2.2)
// ---------------------------------------------------------------------------

/// `seed = Hash(I2OSP(len(Bm), 2) || Bm || I2OSP(len(seedDST), 2) || seedDST)`.
fn composite_seed<G: VoprfGroup>(dsts: &ModeDsts, bm: &G::Element) -> digest::Output<G::Hash> {
    let mut h = G::Hash::new();
    h.update(i2osp2(G::ELEMENT_LEN));
    h.update(bm.as_ref());
    h.update(i2osp2(dsts.seed.len()));
    h.update(dsts.seed);
    h.finalize()
}

/// `di = HashToScalar(I2OSP(len(seed), 2) || seed || I2OSP(i, 2) ||
/// I2OSP(len(Ci), 2) || Ci || I2OSP(len(Di), 2) || Di || "Composite")`.
fn composite_weight<G: VoprfGroup>(
    dsts: &ModeDsts,
    seed: &[u8],
    index: usize,
    pair: &DleqPair<G>,
) -> G::Scalar {
    let ne = i2osp2(G::ELEMENT_LEN);
    G::hash_to_scalar(
        &[
            &i2osp2(seed.len()),
            seed,
            &i2osp2(index),
            &ne,
            pair.c.bytes.as_ref(),
            &ne,
            pair.d.bytes.as_ref(),
            b"Composite",
        ],
        dsts.hash_to_scalar,
    )
}

/// `ComputeComposites` (§2.2.2): the verifier's `(M, Z)`.
fn compute_composites<G: VoprfGroup>(
    dsts: &ModeDsts,
    bm: &G::Element,
    pairs: &[DleqPair<G>],
) -> (G::Point, G::Point) {
    let seed = composite_seed::<G>(dsts, bm);
    let mut m = G::identity();
    let mut z = G::identity();
    for (i, pair) in pairs.iter().enumerate() {
        let di = composite_weight::<G>(dsts, &seed, i, pair);
        m = G::add(&G::mul(&pair.c.point, &di), &m);
        z = G::add(&G::mul(&pair.d.point, &di), &z);
    }
    (m, z)
}

/// `ComputeCompositesFast` (§2.2.1): the prover's `(M, Z = k * M)`.
fn compute_composites_fast<G: VoprfGroup>(
    dsts: &ModeDsts,
    k: &G::Scalar,
    bm: &G::Element,
    pairs: &[DleqPair<G>],
) -> (G::Point, G::Point) {
    let seed = composite_seed::<G>(dsts, bm);
    let mut m = G::identity();
    for (i, pair) in pairs.iter().enumerate() {
        let di = composite_weight::<G>(dsts, &seed, i, pair);
        m = G::add(&G::mul(&pair.c.point, &di), &m);
    }
    let z = G::mul(&m, k);
    (m, z)
}

/// The challenge `c = HashToScalar(I2OSP(len(Bm), 2) || Bm || ... || "Challenge")`
/// over `(Bm, M, Z, t2, t3)`.
///
/// An identity `t2` or `t3` has no encoding on P-256 and cannot come from an
/// honest prover, whose nonce is never zero (erratum 8392); it is rejected
/// with `on_identity` on both suites rather than encoded.
fn challenge<G: VoprfGroup>(
    dsts: &ModeDsts,
    bm: &G::Element,
    a0: &G::Element,
    a1: &G::Element,
    t2: &G::Point,
    t3: &G::Point,
    on_identity: VoprfError,
) -> Result<G::Scalar, VoprfError> {
    let a2 = encode_nonidentity::<G>(t2, on_identity)?;
    let a3 = encode_nonidentity::<G>(t3, on_identity)?;
    let ne = i2osp2(G::ELEMENT_LEN);
    Ok(G::hash_to_scalar(
        &[
            &ne,
            bm.as_ref(),
            &ne,
            a0.as_ref(),
            &ne,
            a1.as_ref(),
            &ne,
            a2.as_ref(),
            &ne,
            a3.as_ref(),
            b"Challenge",
        ],
        dsts.hash_to_scalar,
    ))
}

/// The hedged proof nonce, replacing `r = G.RandomScalar()` in
/// `GenerateProof` (§2.2.1).
///
/// ```text
/// r = HashToScalar(I2OSP(32, 2) || rand || I2OSP(Ns, 2) || SerializeScalar(k)
///                  || I2OSP(Ne, 2) || Bm || I2OSP(Ne, 2) || SerializeElement(M)
///                  || I2OSP(Ne, 2) || SerializeElement(Z),
///                  DST = "pakery-DLEQNonce-" || contextString)
/// ```
///
/// with 32 fresh bytes `rand` from the caller's RNG, redrawn if `r` is zero.
/// The construction follows RFC 9591 §4.1 (`nonce_generate`). A repeated
/// nonce reveals the key — `s = r - c * k` twice gives two equations in `k` —
/// and a plain `RandomScalar` repeats whenever the RNG does: after a fork, a
/// VM snapshot restore, or with a seeded or cloned generator. Hashing the key
/// and the whole statement in makes two different statements get different
/// nonces even then. `(Bm, M, Z)` commits to every `(C[i], D[i])`, because the
/// composite weights hash each pair. The proof stays an ordinary RFC 9497
/// proof; a verifier cannot tell how `r` was chosen.
pub(crate) fn hedged_nonce<G: VoprfGroup>(
    dsts: &ModeDsts,
    rng: &mut impl CryptoRng,
    k: &G::Scalar,
    bm: &G::Element,
    a0: &G::Element,
    a1: &G::Element,
) -> G::Scalar {
    let k_bytes = Zeroizing::new(G::encode_scalar(k));
    let n32 = i2osp2(32);
    let ne = i2osp2(G::ELEMENT_LEN);
    loop {
        let mut rand = Zeroizing::new([0u8; 32]);
        rng.fill_bytes(&mut *rand);
        // ctgrind: fresh nonce randomness is secret.
        ct::mark_secret(&*rand);
        let r = G::hash_to_scalar(
            &[
                &n32,
                &*rand,
                &n32,
                &*k_bytes,
                &ne,
                bm.as_ref(),
                &ne,
                a0.as_ref(),
                &ne,
                a1.as_ref(),
            ],
            dsts.nonce,
        );
        // ctgrind: a zero nonce only triggers a redraw — a public decision.
        // Written as `continue` rather than `if !zero { return }` so no
        // mutant can turn the loop into one that never returns.
        if ct::declassify_choice(r.ct_eq(&G::scalar_zero())) {
            continue;
        }
        return r;
    }
}

/// `GenerateProof(k, G, B, C, D)` (§2.2.1), with the nonce supplied by
/// `nonce(dsts, k, Bm, M, Z)` — [`hedged_nonce`] on every public path, a fixed
/// value in the RFC vector tests.
fn generate_proof<G, N>(
    dsts: &ModeDsts,
    k: &G::Scalar,
    b: &Elem<G>,
    pairs: &[DleqPair<G>],
    nonce: N,
) -> Result<[u8; 64], VoprfError>
where
    G: VoprfGroup,
    N: FnOnce(&ModeDsts, &G::Scalar, &G::Element, &G::Element, &G::Element) -> G::Scalar,
{
    let (m, z) = compute_composites_fast::<G>(dsts, k, &b.bytes, pairs);
    // Unreachable for elements that passed deserialization: M is a sum of
    // nonzero multiples of non-identity elements with hash-derived weights.
    let a0 = encode_nonidentity::<G>(&m, VoprfError::InvalidInput)?;
    let a1 = encode_nonidentity::<G>(&z, VoprfError::InvalidInput)?;
    let r = Zeroizing::new(nonce(dsts, k, &b.bytes, &a0, &a1));
    let t2 = G::mul_base(&r);
    let t3 = G::mul(&m, &r);
    let c = challenge::<G>(dsts, &b.bytes, &a0, &a1, &t2, &t3, VoprfError::InvalidInput)?;
    let ck = Zeroizing::new(G::scalar_mul(&c, k));
    let s = G::scalar_sub(&r, &ck);
    let mut proof = [0u8; 64];
    proof[..32].copy_from_slice(&G::encode_scalar(&c));
    proof[32..].copy_from_slice(&G::encode_scalar(&s));
    // ctgrind: the proof is a wire message.
    ct::declassify(&proof);
    Ok(proof)
}

/// Deserialize a proof `c || s`. Both scalars must be canonical; zero is a
/// valid scalar encoding (§4: `DeserializeScalar` accepts `[0, p - 1]`).
fn parse_proof<G: VoprfGroup>(proof: &[u8]) -> Result<(G::Scalar, G::Scalar), VoprfError> {
    if proof.len() != 64 {
        return Err(VoprfError::Deserialize);
    }
    let mut c_bytes = [0u8; 32];
    let mut s_bytes = [0u8; 32];
    c_bytes.copy_from_slice(&proof[..32]);
    s_bytes.copy_from_slice(&proof[32..]);
    let (c, c_ok) = G::decode_scalar(&c_bytes);
    let (s, s_ok) = G::decode_scalar(&s_bytes);
    if !ct::declassify_choice(c_ok & s_ok) {
        return Err(VoprfError::Deserialize);
    }
    Ok((c, s))
}

/// `VerifyProof(G, B, C, D, proof)` (§2.2.2). Everything it touches is public.
fn verify_proof<G: VoprfGroup>(
    dsts: &ModeDsts,
    b: &Elem<G>,
    pairs: &[DleqPair<G>],
    c: &G::Scalar,
    s: &G::Scalar,
) -> Result<(), VoprfError> {
    let (m, z) = compute_composites::<G>(dsts, &b.bytes, pairs);
    let a0 = encode_nonidentity::<G>(&m, VoprfError::Verify)?;
    let a1 = encode_nonidentity::<G>(&z, VoprfError::Verify)?;
    let t2 = G::add(&G::mul_base(s), &G::mul(&b.point, c));
    let t3 = G::add(&G::mul(&m, s), &G::mul(&z, c));
    let expected = challenge::<G>(dsts, &b.bytes, &a0, &a1, &t2, &t3, VoprfError::Verify)?;
    if !ct::declassify_choice(expected.ct_eq(c)) {
        return Err(VoprfError::Verify);
    }
    Ok(())
}

/// The `Finalize` / `Evaluate` hash: `Hash(I2OSP(len(input), 2) || input
/// [|| I2OSP(len(info), 2) || info] || I2OSP(len(element), 2) || element ||
/// "Finalize")` — with `info` for the POPRF only (§3.3.2, §3.3.3).
fn finalize_hash<G: VoprfGroup>(
    input: &[u8],
    mode: Mode<'_>,
    element: &G::Element,
) -> Result<Zeroizing<G::Output>, VoprfError> {
    let mut h = G::Hash::new();
    h.update(length_prefix(input)?);
    h.update(input);
    if let Mode::Poprf(info) = mode {
        h.update(length_prefix(info)?);
        h.update(info);
    }
    h.update(i2osp2(G::ELEMENT_LEN));
    h.update(element.as_ref());
    h.update(b"Finalize");
    let mut out = Zeroizing::new(G::OUTPUT_ZERO);
    let buf: &mut digest::Output<G::Hash> = out
        .as_mut()
        .try_into()
        .expect("a suite's Output is exactly Nh bytes");
    h.finalize_into(buf);
    Ok(out)
}

// ---------------------------------------------------------------------------
// Server (RFC 9497 SetupVOPRFServer / SetupPOPRFServer)
// ---------------------------------------------------------------------------

/// The server context: `skS` and the cached `pkS`.
pub(crate) struct ServerCore<G: VoprfGroup> {
    sk: G::Scalar,
    pk: Elem<G>,
}

impl<G: VoprfGroup> Zeroize for ServerCore<G> {
    fn zeroize(&mut self) {
        self.sk.zeroize();
    }
}

impl<G: VoprfGroup> Drop for ServerCore<G> {
    fn drop(&mut self) {
        self.zeroize();
    }
}

impl<G: VoprfGroup> ServerCore<G> {
    /// `pkS = ScalarMultGen(skS)`; the caller guarantees `skS != 0`, so `pkS`
    /// is not the identity.
    fn from_nonzero(sk: G::Scalar) -> Self {
        let point = G::mul_base(&sk);
        let bytes = G::encode_element_unchecked(&point);
        // ctgrind: the public key is public.
        ct::declassify(bytes.as_ref());
        Self {
            sk,
            pk: Elem { point, bytes },
        }
    }

    /// `GenerateKeyPair` (§3.2).
    pub(crate) fn generate(rng: &mut impl CryptoRng) -> Self {
        Self::from_nonzero(G::random_scalar(rng))
    }

    /// `DeriveKeyPair(seed, info)` (§3.2.1) under the mode's DST.
    pub(crate) fn derive(mode: Mode<'_>, seed: &[u8; 32], info: &[u8]) -> Result<Self, VoprfError> {
        let dsts = mode.dsts::<G>();
        let info_len = length_prefix(info)?;
        for counter in 0u8..=255 {
            let sk = G::hash_to_scalar(&[seed, &info_len, info, &[counter]], dsts.derive_key_pair);
            // ctgrind: a zero candidate only advances the counter — public.
            if !ct::declassify_choice(sk.ct_eq(&G::scalar_zero())) {
                return Ok(Self::from_nonzero(sk));
            }
        }
        Err(VoprfError::DeriveKeyPair)
    }

    /// `DeserializeScalar(skS)`; zero is rejected, because a zero key makes
    /// every VOPRF evaluation the identity and every POPRF evaluation public.
    pub(crate) fn from_secret_key(bytes: &[u8]) -> Result<Self, VoprfError> {
        let bytes: &[u8; 32] = bytes.try_into().map_err(|_| VoprfError::Deserialize)?;
        let (sk, canonical) = G::decode_scalar(bytes);
        let valid = canonical & !sk.ct_eq(&G::scalar_zero());
        // ctgrind: accepting or rejecting the key is a public decision; the
        // scalar itself stays secret (no laundered copy is parsed).
        if !ct::declassify_choice(valid) {
            return Err(VoprfError::Deserialize);
        }
        Ok(Self::from_nonzero(sk))
    }

    /// `SerializeScalar(skS)`.
    pub(crate) fn secret_key(&self) -> Zeroizing<[u8; 32]> {
        Zeroizing::new(G::encode_scalar(&self.sk))
    }

    /// `SerializeElement(pkS)`.
    pub(crate) fn public_key(&self) -> G::Element {
        self.pk.bytes
    }

    /// A zeroized server holds `skS = 0`; refuse to act as that key rather
    /// than publish evaluations anyone could compute.
    fn check_key(&self) -> Result<(), VoprfError> {
        if ct::declassify_choice(self.sk.ct_eq(&G::scalar_zero())) {
            return Err(VoprfError::Deserialize);
        }
        Ok(())
    }

    /// `t = skS + HashToScalar(framedInfo)`, rejecting `t = 0` (§3.3.3).
    fn tweaked_secret(
        &self,
        dsts: &ModeDsts,
        info: &[u8],
    ) -> Result<Zeroizing<G::Scalar>, VoprfError> {
        let m = info_scalar::<G>(dsts, info)?;
        let t = Zeroizing::new(G::scalar_add(&self.sk, &m));
        // ctgrind: InverseError is a public abort.
        if ct::declassify_choice(t.ct_eq(&G::scalar_zero())) {
            return Err(VoprfError::Inverse);
        }
        Ok(t)
    }

    /// `BlindEvaluate` over a batch with one proof (§3.3.2 / §3.3.3), the
    /// proof nonce supplied by `nonce`.
    pub(crate) fn blind_evaluate<B, N>(
        &self,
        mode: Mode<'_>,
        blinded: &[B],
        nonce: N,
    ) -> Result<(Vec<G::Element>, [u8; 64]), VoprfError>
    where
        B: AsRef<[u8]>,
        N: FnOnce(&ModeDsts, &G::Scalar, &G::Element, &G::Element, &G::Element) -> G::Scalar,
    {
        check_batch_len(blinded.len())?;
        self.check_key()?;
        if let Mode::Poprf(info) = mode {
            length_prefix(info)?;
        }
        let dsts = mode.dsts::<G>();
        let blinded = blinded
            .iter()
            .map(|b| decode_elem::<G>(b.as_ref()))
            .collect::<Result<Vec<_>, _>>()?;

        match mode {
            Mode::Voprf => {
                // GenerateProof(skS, G, pkS, C = blinded, D = evaluated).
                let mut pairs = Vec::with_capacity(blinded.len());
                for c in blinded {
                    let point = G::mul(&c.point, &self.sk);
                    let bytes = encode_nonidentity::<G>(&point, VoprfError::InvalidInput)?;
                    // ctgrind: an evaluated element is a wire message.
                    ct::declassify(bytes.as_ref());
                    pairs.push(DleqPair {
                        c,
                        d: Elem { point, bytes },
                    });
                }
                let proof = generate_proof::<G, N>(&dsts, &self.sk, &self.pk, &pairs, nonce)?;
                Ok((pairs.iter().map(|p| p.d.bytes).collect(), proof))
            }
            Mode::Poprf(info) => {
                let t = self.tweaked_secret(&dsts, info)?;
                let t_inv = Zeroizing::new(G::scalar_invert(&t));
                let tweaked = G::mul_base(&t);
                let tweaked = Elem {
                    point: tweaked,
                    bytes: G::encode_element_unchecked(&tweaked),
                };
                // GenerateProof(t, G, tweakedKey, C = evaluated, D = blinded):
                // the lists are swapped relative to the VOPRF, because
                // t * evaluated == blinded.
                let mut pairs = Vec::with_capacity(blinded.len());
                for d in blinded {
                    let point = G::mul(&d.point, &t_inv);
                    let bytes = encode_nonidentity::<G>(&point, VoprfError::InvalidInput)?;
                    // ctgrind: an evaluated element is a wire message.
                    ct::declassify(bytes.as_ref());
                    pairs.push(DleqPair {
                        c: Elem { point, bytes },
                        d,
                    });
                }
                let proof = generate_proof::<G, N>(&dsts, &t, &tweaked, &pairs, nonce)?;
                Ok((pairs.iter().map(|p| p.c.bytes).collect(), proof))
            }
        }
    }

    /// `Evaluate(skS, input[, info])`: the PRF without blinding (§3.3.1,
    /// §3.3.3).
    pub(crate) fn evaluate(
        &self,
        mode: Mode<'_>,
        input: &[u8],
    ) -> Result<Zeroizing<G::Output>, VoprfError> {
        self.check_key()?;
        length_prefix(input)?;
        if let Mode::Poprf(info) = mode {
            length_prefix(info)?;
        }
        let dsts = mode.dsts::<G>();
        let input_element = Zeroizing::new(G::hash_to_group(input, dsts.hash_to_group)?);
        if ct::declassify_choice(input_element.ct_eq(&G::identity())) {
            return Err(VoprfError::InvalidInput);
        }
        let evaluated = Zeroizing::new(match mode {
            Mode::Voprf => G::mul(&input_element, &self.sk),
            Mode::Poprf(info) => {
                let t = self.tweaked_secret(&dsts, info)?;
                let t_inv = Zeroizing::new(G::scalar_invert(&t));
                G::mul(&input_element, &t_inv)
            }
        });
        // The issued element is the PRF value before hashing: secret.
        let issued = Zeroizing::new(encode_nonidentity::<G>(
            &evaluated,
            VoprfError::InvalidInput,
        )?);
        finalize_hash::<G>(input, mode, &issued)
    }
}

// ---------------------------------------------------------------------------
// Client (RFC 9497 SetupVOPRFClient / SetupPOPRFClient)
// ---------------------------------------------------------------------------

/// The client context: the server's `pkS`.
pub(crate) struct ClientCore<G: VoprfGroup> {
    pk: Elem<G>,
}

/// What the client keeps between `Blind` and `Finalize`.
pub(crate) struct ClientStateCore<G: VoprfGroup> {
    /// The secret blinding scalar.
    blind: G::Scalar,
    /// `HashToGroup(input)`, kept to check the input `finalize` is given. It is
    /// as sensitive as the input: anyone holding it can test guesses.
    input_element: G::Point,
    /// The blinded element sent to the server (public).
    blinded: Elem<G>,
    /// The POPRF tweaked key `Blind` derived from the client's `pkS` and
    /// `info` — RFC 9497 §3.3.3: "Clients store the outputs blind and
    /// tweakedKey locally" — and `None` for the VOPRF. Public.
    tweaked_key: Option<Elem<G>>,
}

impl<G: VoprfGroup> Zeroize for ClientStateCore<G> {
    fn zeroize(&mut self) {
        self.blind.zeroize();
        self.input_element.zeroize();
    }
}

impl<G: VoprfGroup> Drop for ClientStateCore<G> {
    fn drop(&mut self) {
        self.zeroize();
    }
}

impl<G: VoprfGroup> ClientCore<G> {
    /// `DeserializeElement(pkS)`.
    pub(crate) fn new(public_key: &[u8]) -> Result<Self, VoprfError> {
        Ok(Self {
            pk: decode_elem::<G>(public_key)?,
        })
    }

    /// `tweakedKey = HashToScalar(framedInfo) * G + pkS`, rejecting the
    /// identity (§3.3.3).
    fn tweaked_key(&self, dsts: &ModeDsts, info: &[u8]) -> Result<Elem<G>, VoprfError> {
        let m = info_scalar::<G>(dsts, info)?;
        let point = G::add(&G::mul_base(&m), &self.pk.point);
        let bytes = encode_nonidentity::<G>(&point, VoprfError::InvalidInput)?;
        Ok(Elem { point, bytes })
    }

    /// What `Blind` checks and derives before it draws a blind: the input
    /// length, and for the POPRF the tweaked key, which the state keeps
    /// (§3.3.3 raises `InvalidInputError` here, so a bad `info` fails before a
    /// request is sent).
    fn blind_inputs(&self, mode: Mode<'_>, input: &[u8]) -> Result<Option<Elem<G>>, VoprfError> {
        length_prefix(input)?;
        match mode {
            Mode::Voprf => Ok(None),
            Mode::Poprf(info) => self.tweaked_key(&mode.dsts::<G>(), info).map(Some),
        }
    }

    /// `Blind` (§3.3.1 / §3.3.3) with a random blind.
    pub(crate) fn blind(
        &self,
        mode: Mode<'_>,
        input: &[u8],
        rng: &mut impl CryptoRng,
    ) -> Result<(ClientStateCore<G>, G::Element), VoprfError> {
        let tweaked_key = self.blind_inputs(mode, input)?;
        let blind = Zeroizing::new(G::random_scalar(rng));
        blind_with::<G>(&mode.dsts::<G>(), input, &blind, tweaked_key)
    }

    /// `Blind` with a blind reduced from 64 caller-supplied bytes.
    #[cfg(feature = "hazmat")]
    pub(crate) fn deterministic_blind(
        &self,
        mode: Mode<'_>,
        input: &[u8],
        blind: &[u8; 64],
    ) -> Result<(ClientStateCore<G>, G::Element), VoprfError> {
        let tweaked_key = self.blind_inputs(mode, input)?;
        let blind = Zeroizing::new(G::scalar_from_wide(blind));
        // A zero blind would send the identity; the decision is public.
        if ct::declassify_choice(blind.ct_eq(&G::scalar_zero())) {
            return Err(VoprfError::InvalidInput);
        }
        blind_with::<G>(&mode.dsts::<G>(), input, &blind, tweaked_key)
    }

    /// `Finalize` over a batch with one proof (§3.3.2 / §3.3.3).
    ///
    /// Every check on the caller's own arguments runs before anything the
    /// server sent is parsed: batch shape; lengths; that each state is live
    /// and was blinded from the input given here; for the POPRF, that the
    /// tweaked key this `info` and this client's `pkS` give is the one each
    /// state stored. Only then the evaluated elements, the proof encoding and
    /// the proof itself — so only `Deserialize` of the response and `Verify`
    /// blame the server.
    pub(crate) fn finalize<I, E>(
        &self,
        mode: Mode<'_>,
        states: &[&ClientStateCore<G>],
        inputs: &[I],
        evaluated: &[E],
        proof: &[u8],
    ) -> Result<Vec<Zeroizing<G::Output>>, VoprfError>
    where
        I: AsRef<[u8]>,
        E: AsRef<[u8]>,
    {
        let n = states.len();
        check_batch_len(n)?;
        if inputs.len() != n || evaluated.len() != n {
            return Err(VoprfError::Batch);
        }
        for input in inputs {
            length_prefix(input.as_ref())?;
        }
        if let Mode::Poprf(info) = mode {
            length_prefix(info)?;
        }
        let dsts = mode.dsts::<G>();

        for (state, input) in states.iter().zip(inputs) {
            // A zeroized state has a zero blind, which cannot be inverted.
            if ct::declassify_choice(state.blind.ct_eq(&G::scalar_zero())) {
                return Err(VoprfError::InvalidInput);
            }
            let input_element =
                Zeroizing::new(G::hash_to_group(input.as_ref(), dsts.hash_to_group)?);
            // ctgrind: whether the input matches is a public abort decision.
            if !ct::declassify_choice(input_element.ct_eq(&state.input_element)) {
                return Err(VoprfError::InputMismatch);
            }
        }

        // The POPRF tweaked key: recomputed from this `info` and this client's
        // `pkS`, and required to equal the one `Blind` stored in every state.
        // A different `info`, or a state blinded by a client holding another
        // key, is the caller's error, not the server's.
        let tweaked = match mode {
            Mode::Voprf => None,
            Mode::Poprf(info) => {
                let tweaked = self.tweaked_key(&dsts, info)?;
                for state in states {
                    let stored = state
                        .tweaked_key
                        .map_or(Choice::from(0), |t| t.point.ct_eq(&tweaked.point));
                    // ctgrind: public points; the decision is public as well.
                    if !ct::declassify_choice(stored) {
                        return Err(VoprfError::InputMismatch);
                    }
                }
                Some(tweaked)
            }
        };

        let evaluated = evaluated
            .iter()
            .map(|e| decode_elem::<G>(e.as_ref()))
            .collect::<Result<Vec<_>, _>>()?;
        let (c, s) = parse_proof::<G>(proof)?;

        match tweaked {
            None => {
                // VerifyProof(G, pkS, C = blinded, D = evaluated).
                let pairs: Vec<_> = states
                    .iter()
                    .zip(&evaluated)
                    .map(|(state, d)| DleqPair {
                        c: state.blinded,
                        d: *d,
                    })
                    .collect();
                verify_proof::<G>(&dsts, &self.pk, &pairs, &c, &s)?;
            }
            Some(tweaked) => {
                // VerifyProof(G, tweakedKey, C = evaluated, D = blinded).
                let pairs: Vec<_> = states
                    .iter()
                    .zip(&evaluated)
                    .map(|(state, c)| DleqPair {
                        c: *c,
                        d: state.blinded,
                    })
                    .collect();
                verify_proof::<G>(&dsts, &tweaked, &pairs, &c, &s)?;
            }
        }

        let mut outputs = Vec::with_capacity(n);
        for ((state, input), z) in states.iter().zip(inputs).zip(&evaluated) {
            let blind_inv = Zeroizing::new(G::scalar_invert(&state.blind));
            let unblinded = Zeroizing::new(G::mul(&z.point, &blind_inv));
            // Unreachable: a non-identity Z times a nonzero scalar. Checked
            // anyway, because the encoding needs it on P-256.
            let unblinded = Zeroizing::new(encode_nonidentity::<G>(
                &unblinded,
                VoprfError::InvalidInput,
            )?);
            outputs.push(finalize_hash::<G>(input.as_ref(), mode, &unblinded)?);
        }
        Ok(outputs)
    }
}

/// The rest of `Blind`: `inputElement = HashToGroup(input)`, rejecting the
/// identity, then `blindedElement = blind * inputElement`.
fn blind_with<G: VoprfGroup>(
    dsts: &ModeDsts,
    input: &[u8],
    blind: &G::Scalar,
    tweaked_key: Option<Elem<G>>,
) -> Result<(ClientStateCore<G>, G::Element), VoprfError> {
    let input_element = Zeroizing::new(G::hash_to_group(input, dsts.hash_to_group)?);
    if ct::declassify_choice(input_element.ct_eq(&G::identity())) {
        return Err(VoprfError::InvalidInput);
    }
    let point = G::mul(&input_element, blind);
    // Not the identity: a nonzero blind times a non-identity element.
    let bytes = G::encode_element_unchecked(&point);
    // ctgrind: the blinded element is the wire message (blinding hides the
    // input).
    ct::declassify(bytes.as_ref());
    let state = ClientStateCore {
        blind: *blind,
        input_element: *input_element,
        blinded: Elem { point, bytes },
        tweaked_key,
    };
    Ok((state, bytes))
}

#[cfg(test)]
pub(crate) mod test_support {
    //! Helpers shared by the per-suite unit tests.

    use super::*;

    /// Decode a hex string (test data only).
    pub(crate) fn hex(s: &str) -> Vec<u8> {
        assert!(s.len() % 2 == 0, "odd-length hex");
        (0..s.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex digit"))
            .collect()
    }

    /// An RNG that replays a fixed byte string and panics when it runs out,
    /// so a test can never silently consume more randomness than it scripted.
    pub(crate) struct ScriptedRng {
        bytes: Vec<u8>,
        pos: usize,
    }

    impl ScriptedRng {
        pub(crate) fn new(bytes: &[u8]) -> Self {
            Self {
                bytes: bytes.to_vec(),
                pos: 0,
            }
        }

        pub(crate) fn is_exhausted(&self) -> bool {
            self.pos == self.bytes.len()
        }
    }

    impl rand_core::TryRng for ScriptedRng {
        type Error = core::convert::Infallible;

        fn try_next_u32(&mut self) -> Result<u32, Self::Error> {
            let mut b = [0u8; 4];
            self.try_fill_bytes(&mut b)?;
            Ok(u32::from_le_bytes(b))
        }

        fn try_next_u64(&mut self) -> Result<u64, Self::Error> {
            let mut b = [0u8; 8];
            self.try_fill_bytes(&mut b)?;
            Ok(u64::from_le_bytes(b))
        }

        fn try_fill_bytes(&mut self, dst: &mut [u8]) -> Result<(), Self::Error> {
            let end = self.pos + dst.len();
            assert!(end <= self.bytes.len(), "ScriptedRng exhausted");
            dst.copy_from_slice(&self.bytes[self.pos..end]);
            self.pos = end;
            Ok(())
        }
    }

    impl rand_core::TryCryptoRng for ScriptedRng {}

    /// A proof whose `t2` and `t3` are both the identity: `s = -c * k` for a
    /// `c` hashed over the identity's encoding where `t2` and `t3` go. It
    /// proves a true statement — the server knows `k` — and an RFC-literal
    /// verifier on ristretto255, where the identity encodes as 32 zero bytes,
    /// accepts it. This crate rejects it on both suites.
    pub(crate) fn degenerate_proof<G: VoprfGroup>(
        server: &ServerCore<G>,
        mode: Mode<'_>,
        blinded: &[u8],
        evaluated: &[u8],
    ) -> [u8; 64] {
        let dsts = mode.dsts::<G>();
        let blinded = decode_elem::<G>(blinded).unwrap();
        let evaluated = decode_elem::<G>(evaluated).unwrap();
        let (k, b, pair) = match mode {
            Mode::Voprf => (
                server.sk,
                server.pk,
                DleqPair {
                    c: blinded,
                    d: evaluated,
                },
            ),
            Mode::Poprf(info) => {
                let t = *server.tweaked_secret(&dsts, info).unwrap();
                let point = G::mul_base(&t);
                let b = Elem {
                    point,
                    bytes: G::encode_element_unchecked(&point),
                };
                (
                    t,
                    b,
                    DleqPair {
                        c: evaluated,
                        d: blinded,
                    },
                )
            }
        };
        let (m, z) = compute_composites::<G>(&dsts, &b.bytes, core::slice::from_ref(&pair));
        let ne = i2osp2(G::ELEMENT_LEN);
        let id = G::encode_element_unchecked(&G::identity());
        let c = G::hash_to_scalar(
            &[
                &ne,
                b.bytes.as_ref(),
                &ne,
                G::encode_element_unchecked(&m).as_ref(),
                &ne,
                G::encode_element_unchecked(&z).as_ref(),
                &ne,
                id.as_ref(),
                &ne,
                id.as_ref(),
                b"Challenge",
            ],
            dsts.hash_to_scalar,
        );
        let s = G::scalar_sub(&G::scalar_zero(), &G::scalar_mul(&c, &k));
        let mut proof = [0u8; 64];
        proof[..32].copy_from_slice(&G::encode_scalar(&c));
        proof[32..].copy_from_slice(&G::encode_scalar(&s));
        proof
    }

    /// The secret key whose POPRF tweaked key is zero for `info`:
    /// `skS = -HashToScalar(framedInfo)`.
    pub(crate) fn key_with_zero_tweak<G: VoprfGroup>(info: &[u8]) -> [u8; 32] {
        let m = info_scalar::<G>(&G::POPRF, info).unwrap();
        G::encode_scalar(&G::scalar_sub(&G::scalar_zero(), &m))
    }

    /// Whether a server's secret key is all zero.
    pub(crate) fn server_key_is_zero<G: VoprfGroup>(server: &ServerCore<G>) -> bool {
        bool::from(server.sk.ct_eq(&G::scalar_zero()))
    }

    /// Whether a client state's secrets are wiped: a zero blind and an
    /// identity input element.
    pub(crate) fn state_is_wiped<G: VoprfGroup>(state: &ClientStateCore<G>) -> bool {
        bool::from(state.blind.ct_eq(&G::scalar_zero()))
            && bool::from(state.input_element.ct_eq(&G::identity()))
    }

    /// `BlindEvaluate` with an explicit proof nonce, for the RFC 9497 "Proof"
    /// vectors. Not reachable outside this crate's own unit tests.
    pub(crate) fn blind_evaluate_with_nonce<G: VoprfGroup, B: AsRef<[u8]>>(
        server: &ServerCore<G>,
        mode: Mode<'_>,
        blinded: &[B],
        r: G::Scalar,
    ) -> Result<(Vec<G::Element>, [u8; 64]), VoprfError> {
        server.blind_evaluate(mode, blinded, move |_, _, _, _, _| r)
    }

    /// The nonce `r = s + c * k` of a proof made with this server's key — `skS`
    /// for the VOPRF, the tweaked key `t` for the POPRF. Tests compare nonces
    /// rather than proofs: `c` hashes the whole statement, so the proofs of two
    /// statements differ whatever their nonces.
    pub(crate) fn proof_nonce<G: VoprfGroup>(
        server: &ServerCore<G>,
        mode: Mode<'_>,
        proof: &[u8; 64],
    ) -> [u8; 32] {
        let (c, s) = parse_proof::<G>(proof).unwrap();
        let k = match mode {
            Mode::Voprf => server.sk,
            Mode::Poprf(info) => *server.tweaked_secret(&mode.dsts::<G>(), info).unwrap(),
        };
        G::encode_scalar(&G::scalar_add(&s, &G::scalar_mul(&c, &k)))
    }

    /// `proof` with the scalar at `offset` (0 for `c`, 32 for `s`) replaced by
    /// that scalar plus one: still a canonical encoding, so it parses.
    pub(crate) fn bump_proof_scalar<G: VoprfGroup>(proof: &[u8; 64], offset: usize) -> [u8; 64] {
        let bytes: [u8; 32] = proof[offset..offset + 32].try_into().unwrap();
        let (x, canonical) = G::decode_scalar(&bytes);
        assert!(bool::from(canonical) && !bool::from(x.ct_eq(&G::scalar_zero())));
        let one = G::scalar_mul(&G::scalar_invert(&x), &x);
        let mut out = *proof;
        out[offset..offset + 32].copy_from_slice(&G::encode_scalar(&G::scalar_add(&x, &one)));
        out
    }
}

#[cfg(test)]
mod dst_tests {
    use super::*;
    use alloc::vec::Vec;

    /// `CreateContextString(mode, identifier)` (RFC 9497 §3.1).
    fn context(mode: u8, identifier: &[u8]) -> Vec<u8> {
        [b"OPRFV1-".as_slice(), &[mode], b"-", identifier].concat()
    }

    /// Rebuild every tag of a suite from its parts and compare with the
    /// literals: a typo in either place fails here, before any vector does.
    fn check_suite<G: VoprfGroup>(identifier: &[u8]) {
        for (mode, dsts) in [(0x01u8, G::VOPRF), (0x02, G::POPRF)] {
            let ctx = context(mode, identifier);
            let with = |prefix: &[u8]| [prefix, ctx.as_slice()].concat();
            assert_eq!(dsts.hash_to_group, with(b"HashToGroup-"));
            assert_eq!(dsts.hash_to_scalar, with(b"HashToScalar-"));
            assert_eq!(dsts.derive_key_pair, with(b"DeriveKeyPair"));
            assert_eq!(dsts.seed, with(b"Seed-"));
            assert_eq!(dsts.nonce, with(b"pakery-DLEQNonce-"));
            for dst in [
                dsts.hash_to_group,
                dsts.hash_to_scalar,
                dsts.derive_key_pair,
                dsts.nonce,
            ] {
                assert!(
                    dst.len() <= 255,
                    "expand_message_xmd DSTs are at most 255 bytes"
                );
            }
        }
        // The two modes never share a tag.
        assert_ne!(G::VOPRF.hash_to_scalar, G::POPRF.hash_to_scalar);
    }

    #[cfg(feature = "ristretto255")]
    #[test]
    fn ristretto255_dsts_match_create_context_string() {
        check_suite::<super::super::suite_ristretto255::Ristretto255>(b"ristretto255-SHA512");
    }

    #[cfg(feature = "p256")]
    #[test]
    fn p256_dsts_match_create_context_string() {
        check_suite::<super::super::suite_p256::P256>(b"P256-SHA256");
    }

    /// `finalize_into` writes the hash straight into the suite's output
    /// buffer; this pins that the buffer is exactly `Nh` bytes, so the
    /// conversion in `finalize_hash` cannot fail.
    #[test]
    fn output_buffers_are_hash_sized() {
        #[cfg(feature = "ristretto255")]
        {
            type G = super::super::suite_ristretto255::Ristretto255;
            assert_eq!(
                <<G as VoprfGroup>::Hash as Digest>::output_size(),
                G::OUTPUT_ZERO.len()
            );
        }
        #[cfg(feature = "p256")]
        {
            type G = super::super::suite_p256::P256;
            assert_eq!(
                <<G as VoprfGroup>::Hash as Digest>::output_size(),
                G::OUTPUT_ZERO.len()
            );
        }
    }
}
